head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.gAcptNo; // 접수번호
scwin.gEmpNo;
scwin.vScrenID = 'ULDSTF10004.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// 부모창의 데이타 셋팅하기
scwin.fn_setParamData = function() {
    //gAcptNo = frame.Provider("/frame_head").dts_AcptProcs.NameString(1, 'ACPT_NO');
    scwin.gAcptNo = $c.frame.path("../../frame_head").dts_AcptProcs.getCellData(1, 'ACPT_NO');
    scwin.gEmpNo = js_emp_no; // 세션정보 			

};
scwin.fn_Insert = function() {
    var vReason = $c.stf.getObjectValue(txa_AgainReason);
    if (vReason.length < 1) {
        $c.win.alert("기처리 사유를 입력하시오.");
        txa_AgainReason.focus();
        return;
    }
    $c.stf.checkMaxLength(txa_AgainReason, 500, '기처리사유');
    dts_again.insertRow();
    dts_again.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_again.setCellData(1, "AGAIN_REASON", vReason);
    dts_again.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_again.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    var vAnswer = confirm('입력하신 사유로 기처리 하시겠습니까?');
    if (vAnswer == true) {
        //alert(dts_again.text);
        trs_again.Action = "/DisclosureStudy.do?method=processDisclosureAgain&inputMessageId=DSCLAGAIN_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo;
        trs_again.KeyName = "toinb_dataid4";
        trs_again.KeyValue = "JSP(I:pInput=dts_again)";
        trs_again.Post();
    }
};
scwin.trs_again_OnSuccess = async function() {
    $c.win.alert("성공적으로 기처리가 되었습니다.");
    await $c.frame.CloseFrame();

    // 부모창 reload 처리해야함
    //frame.Provider("/frame_head").fn_HeadRead() ;
    //frame.Provider("../../frame_head").fn_HeadRead() ;

};
scwin.trs_again_OnFail = function() {
    $c.win.alert('trs_again.OnFail() :' + trs_again.ErrorMsg);
    dts_again.Reset();
};
scwin.btn_Cancle_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Insert();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(pnl_1);

    // 가우스헤더 셋팅
    dts_again.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLAGAIN_IN";
    dts_again.reset();
    scwin.fn_setParamData();
};
